CREATE TABLE mutation_input (seq BIGINT, scope_key TEXT, item_id BIGINT, mode TEXT, quantity BIGINT, label TEXT, enabled BOOLEAN) WITH (connector = 'single_file', path = '{directory}/input.jsonl', format = 'json', type = 'source', wait_for_control = 'true');
CREATE TABLE mutation_output (seq BIGINT, scope_key TEXT, item_id BIGINT, mode TEXT, quantity BIGINT, label TEXT, enabled BOOLEAN, first_old_scope_key TEXT, first_old_item_id BIGINT, first_old_quantity BIGINT, first_old_label TEXT, first_old_enabled BOOLEAN, first_new_scope_key TEXT, first_new_item_id BIGINT, first_new_quantity BIGINT, first_new_label TEXT, first_new_enabled BOOLEAN, first_action TEXT, second_old_scope_key TEXT, second_old_item_id BIGINT, second_old_quantity BIGINT, second_old_label TEXT, second_old_enabled BOOLEAN, second_new_scope_key TEXT, second_new_item_id BIGINT, second_new_quantity BIGINT, second_new_label TEXT, second_new_enabled BOOLEAN, second_action TEXT, lookup_scope_key TEXT, lookup_item_id BIGINT, lookup_quantity BIGINT, lookup_label TEXT, lookup_enabled BOOLEAN) WITH (connector = 'single_file', path = '{directory}/output.jsonl', format = 'json', type = 'sink');
CREATE TABLE mutation_mirror (seq BIGINT, scope_key TEXT, item_id BIGINT, mode TEXT, quantity BIGINT, label TEXT, enabled BOOLEAN, first_old_scope_key TEXT, first_old_item_id BIGINT, first_old_quantity BIGINT, first_old_label TEXT, first_old_enabled BOOLEAN, first_new_scope_key TEXT, first_new_item_id BIGINT, first_new_quantity BIGINT, first_new_label TEXT, first_new_enabled BOOLEAN, first_action TEXT, second_old_scope_key TEXT, second_old_item_id BIGINT, second_old_quantity BIGINT, second_old_label TEXT, second_old_enabled BOOLEAN, second_new_scope_key TEXT, second_new_item_id BIGINT, second_new_quantity BIGINT, second_new_label TEXT, second_new_enabled BOOLEAN, second_action TEXT, lookup_scope_key TEXT, lookup_item_id BIGINT, lookup_quantity BIGINT, lookup_label TEXT, lookup_enabled BOOLEAN) WITH (connector = 'single_file', path = '{directory}/mirror.jsonl', format = 'json', type = 'sink');
CREATE TABLE mutation_mid (seq BIGINT, scope_key TEXT, item_id BIGINT, mode TEXT, quantity BIGINT, label TEXT, enabled BOOLEAN, first_old_scope_key TEXT, first_old_item_id BIGINT, first_old_quantity BIGINT, first_old_label TEXT, first_old_enabled BOOLEAN, first_new_scope_key TEXT, first_new_item_id BIGINT, first_new_quantity BIGINT, first_new_label TEXT, first_new_enabled BOOLEAN, first_action TEXT) WITH (connector = 'single_file', path = '{directory}/mid.jsonl', format = 'json', type = 'sink');
CREATE STATE TABLE inventory (scope_key TEXT, item_id BIGINT, quantity BIGINT, label TEXT, enabled BOOLEAN, PRIMARY KEY (scope_key, item_id)) PARTITION BY scope_key;
CREATE STATE TABLE observed (scope_key TEXT, item_id BIGINT, quantity BIGINT, label TEXT, enabled BOOLEAN, PRIMARY KEY (scope_key, item_id)) PARTITION BY scope_key;
CREATE VIEW applied AS MERGE INTO inventory AS target USING mutation_input AS source
ON target.scope_key = source.scope_key AND target.item_id = source.item_id
WHEN MATCHED AND source.mode = 'delete' THEN DELETE
WHEN MATCHED AND source.mode = 'write' THEN UPDATE SET quantity = source.quantity, label = source.label, enabled = source.enabled
WHEN NOT MATCHED AND source.mode = 'write' THEN INSERT (scope_key, item_id, quantity, label, enabled) VALUES (source.scope_key, source.item_id, source.quantity, source.label, source.enabled)
RETURNING source AS source, old AS old, new AS new, action AS action;
CREATE VIEW dependent_events AS SELECT source.seq AS seq, source.scope_key AS scope_key, source.item_id AS item_id, source.mode AS mode, source.quantity AS quantity, source.label AS label, source.enabled AS enabled,
old.scope_key AS first_old_scope_key, old.item_id AS first_old_item_id, old.quantity AS first_old_quantity, old.label AS first_old_label, old.enabled AS first_old_enabled,
new.scope_key AS first_new_scope_key, new.item_id AS first_new_item_id, new.quantity AS first_new_quantity, new.label AS first_new_label, new.enabled AS first_new_enabled, action AS first_action FROM applied;
CREATE VIEW dependent_applied AS MERGE INTO observed AS target USING dependent_events AS source
ON target.scope_key = source.scope_key AND target.item_id = source.item_id
WHEN MATCHED AND source.first_action = 'delete' THEN DELETE
WHEN MATCHED AND source.first_action IN ('insert', 'update') THEN UPDATE SET quantity = source.first_new_quantity, label = source.first_new_label, enabled = source.first_new_enabled
WHEN NOT MATCHED AND source.first_action IN ('insert', 'update') THEN INSERT (scope_key, item_id, quantity, label, enabled) VALUES (source.scope_key, source.item_id, source.first_new_quantity, source.first_new_label, source.first_new_enabled)
RETURNING source AS source, old AS old, new AS new, action AS action;
CREATE VIEW checked AS SELECT r.source.seq AS seq, r.source.scope_key AS scope_key, r.source.item_id AS item_id, r.source.mode AS mode, r.source.quantity AS quantity, r.source.label AS label, r.source.enabled AS enabled,
r.source.first_old_scope_key AS first_old_scope_key, r.source.first_old_item_id AS first_old_item_id, r.source.first_old_quantity AS first_old_quantity, r.source.first_old_label AS first_old_label, r.source.first_old_enabled AS first_old_enabled,
r.source.first_new_scope_key AS first_new_scope_key, r.source.first_new_item_id AS first_new_item_id, r.source.first_new_quantity AS first_new_quantity, r.source.first_new_label AS first_new_label, r.source.first_new_enabled AS first_new_enabled, r.source.first_action AS first_action,
r.old.scope_key AS second_old_scope_key, r.old.item_id AS second_old_item_id, r.old.quantity AS second_old_quantity, r.old.label AS second_old_label, r.old.enabled AS second_old_enabled,
r.new.scope_key AS second_new_scope_key, r.new.item_id AS second_new_item_id, r.new.quantity AS second_new_quantity, r.new.label AS second_new_label, r.new.enabled AS second_new_enabled, r.action AS second_action,
i.scope_key AS lookup_scope_key, i.item_id AS lookup_item_id, i.quantity AS lookup_quantity, i.label AS lookup_label, i.enabled AS lookup_enabled
FROM dependent_applied r LEFT JOIN inventory i ON i.scope_key = r.source.scope_key AND i.item_id = r.source.item_id;
INSERT INTO mutation_mid SELECT * FROM dependent_events;
INSERT INTO mutation_output SELECT * FROM checked;
INSERT INTO mutation_mirror SELECT * FROM checked;
